17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Map;
28	import java.util.Objects;
29	
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	import org.springframework.http.HttpHeaders;
33	import org.springframework.http.HttpStatus;
34	import org.springframework.http.ResponseEntity;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    private final AddressNormalizer addressNormalizer;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper,
82	                                 AddressNormalizer addressNormalizer) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	        this.addressNormalizer = addressNormalizer;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        String address = addressNormalizer.normalize(owner.getAddress());
121	        if (address.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        owner.setAddress(address);
125	        String telephone = toE164(owner.getTelephone());
126	        if (telephone == null) {
127	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
128	        }
129	        owner.setTelephone(telephone);
130	        LocalDate effectiveDate = owner.getRegistrationDate() != null
131	            ? owner.getRegistrationDate() : LocalDate.now();
132	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
133	        if (isDailyLimitReached(owner.getRegistrationDate())) {
134	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
135	        }
136	        if (isTelephoneInUse(telephone)) {
137	            return new ResponseEntity<>(HttpStatus.CONFLICT);
138	        }
139	        if (isEmailInUse(owner.getEmail())) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
143	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
144	            return new ResponseEntity<>(HttpStatus.CONFLICT);
145	        }
146	        if (sharesHousehold) {
147	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
148	        }
149	        if (isCityAtCapacity(owner.getCity())) {
150	            return new ResponseEntity<>(HttpStatus.CONFLICT);
151	        }
152	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
153	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
154	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
155	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
156	        this.clinicService.saveOwner(owner);
157	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
158	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    /**
166	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
167	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
168	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
169	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
170	     */
171	    private String nextCustomerCode(String city, String lastName) {
172	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
173	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
174	        int sequence = (int) this.clinicService.findAllOwners().stream()
175	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
176	            .count() + 1;
177	        return String.format("%s-%s-%04d", city3, last3, sequence);
178	    }
179	
180	    /**
181	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
182	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
183	     * (business-day) registration date of the owner being created, so owners are counted per
184	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
185	     */
186	    private boolean isDailyLimitReached(LocalDate day) {
187	        long count = this.clinicService.findAllOwners().stream()
188	            .filter(existing -> day.equals(existing.getRegistrationDate()))
189	            .count();
190	        return count >= 100;
191	    }
192	
193	    /**
194	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
195	     * more than 80 owners have already been created for the given business day. Counts the owners
196	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
197	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
198	     * warning.
199	     */
200	    private boolean isBulkSignup(LocalDate day) {
201	        long count = this.clinicService.findAllOwners().stream()
202	            .filter(existing -> day.equals(existing.getRegistrationDate()))
203	            .count();
204	        return count > 80;
205	    }
206	
207	    /**
208	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
209	     * advance it to the following Monday; a weekday is returned unchanged.
210	     */
211	    private LocalDate toBusinessDay(LocalDate date) {
212	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
213	            date = date.plusDays(1);
214	        }
215	        return date;
216	    }
217	
218	    /**
219	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
220	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
221	     */
222	    private boolean isCityAtCapacity(String city) {
223	        long count = this.clinicService.findAllOwners().stream()
224	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
225	            .count();
226	        return count >= 50;
227	    }
228	
229	    /**
230	     * The number of existing owners that already share the given firstName and lastName,
231	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
232	     * whitespace runs collapsed). Counted over the owners present before this create.
233	     */
234	    private int namesakeCount(String firstName, String lastName) {
235	        String candidateFirstName = normalizeName(firstName);
236	        String candidateLastName = normalizeName(lastName);
237	        return (int) this.clinicService.findAllOwners().stream()
238	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
239	                && normalizeName(existing.getLastName()).equals(candidateLastName))
240	            .count();
241	    }
242	
243	    /**
244	     * The number of members in this owner's household after this create: the count of existing
245	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
246	     * created. An owner with no household ({@code householdId == null}) is a household of one.
247	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
248	     * does not depend on the order in which household members were created.
249	     */
250	    private int householdSize(String householdId) {
251	        if (householdId == null) {
252	            return 1;
253	        }
254	        long existing = this.clinicService.findAllOwners().stream()
255	            .filter(other -> householdId.equals(other.getHouseholdId()))
256	            .count();
257	        return (int) existing + 1;
258	    }
259	
260	    /**
261	     * The number of national (subscriber) digits required for each known country calling
262	     * code, keyed by the code's digits (without the leading '+'). A number whose country
263	     * code appears here must carry exactly this many digits after the code, e.g. '+61'
264	     * requires 9 national digits and '+1' requires 10.
265	     */
266	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
267	        "1", 10,
268	        "61", 9);
269	
270	    /**
271	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
272	     * cannot form a valid E.164 number.
273	     *
274	     * <p>A leading '+' and country code are kept when present; otherwise country code
275	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
276	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
277	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
278	     * exactly the national-digit count that code requires (see
279	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}); otherwise it is rejected as invalid.
280	     */
281	    private String toE164(String telephone) {
282	        if (telephone == null) {
283	            return null;
284	        }
285	        boolean hasCountryCode = telephone.trim().startsWith("+");
286	        String digits = telephone.replaceAll("\\D", "");
287	        String e164;
288	        if (hasCountryCode) {
289	            e164 = digits;
290	        } else {
291	            if (digits.startsWith("0")) {
292	                digits = digits.substring(1);
293	            }
294	            e164 = "61" + digits;
295	        }
296	        if (e164.length() < 8 || e164.length() > 15) {
297	            return null;
298	        }
299	        if (!hasValidNationalLength(e164)) {
300	            return null;
301	        }
302	        return "+" + e164;
303	    }
304	
305	    /**
306	     * Whether the E.164 digit string (no leading '+') carries the national-number length
307	     * required by its country calling code. The longest matching known code wins; a number
308	     * whose country code is not recognised passes this check (its length is governed only by
309	     * the general 8-15 digit bound in {@link #toE164}).
310	     */
311	    private boolean hasValidNationalLength(String e164) {
312	        return NATIONAL_DIGITS_BY_COUNTRY.entrySet().stream()
313	            .filter(entry -> e164.startsWith(entry.getKey()))
314	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
315	            .map(entry -> e164.length() - entry.getKey().length() == entry.getValue())
316	            .orElse(true);
317	    }
318	
319	    /**
320	     * Whether any existing owner already holds the given telephone number. Both the
321	     * candidate and each stored number are compared in E.164 form, so the check does not
322	     * depend on how each was originally formatted.
323	     */
324	    private boolean isTelephoneInUse(String telephone) {
325	        return this.clinicService.findAllOwners().stream()
326	            .map(Owner::getTelephone)
327	            .filter(Objects::nonNull)
328	            .map(this::toE164)
329	            .filter(Objects::nonNull)
330	            .anyMatch(telephone::equals);
331	    }
332	
333	    /**
334	     * Whether any existing owner already holds the given email address, compared case-insensitively
335	     * (by lower-casing both the candidate and each stored value). A null or empty candidate email is
336	     * never considered in use, so owners without an email do not collide. When true, the new owner
337	     * must be rejected with {@code 409 Conflict}.
338	     */
339	    private boolean isEmailInUse(String email) {
340	        if (email == null || email.isEmpty()) {
341	            return false;
342	        }
343	        String candidate = email.toLowerCase();
344	        return this.clinicService.findAllOwners().stream()
345	            .map(Owner::getEmail)
346	            .filter(Objects::nonNull)
347	            .map(String::toLowerCase)
348	            .anyMatch(candidate::equals);
349	    }
350	
351	    /**
352	     * Whether any existing owner already shares a household with the candidate, i.e. has both
353	     * the same lastName and the same address. Both fields are compared case-insensitively and
354	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
355	     * trimmed), so the check does not depend on casing or spacing.
356	     */
357	    private boolean isHouseholdInUse(String lastName, String address) {
358	        String candidateLastName = normalizeName(lastName);
359	        String candidateAddress = addressNormalizer.normalize(address);
360	        return this.clinicService.findAllOwners().stream()
361	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
362	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
363	    }
364	
365	    /**
366	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
367	     * to a single space and lower-case. A null value normalizes to the empty string.
368	     */
369	    private String normalizeName(String value) {
370	        if (value == null) {
371	            return "";
372	        }
373	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
374	    }
375	
376	    /**
377	     * A stable shared identifier for the household formed by a given lastName and address.
378	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
379	     * lastName and address, so every owner sharing the same household is assigned the same
380	     * value regardless of the order in which they are created. Formatted as the first 12
381	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
382	     */
383	    private String householdId(String lastName, String address) {
384	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
385	        try {
386	            byte[] digest = MessageDigest.getInstance("SHA-256")
387	                .digest(key.getBytes(StandardCharsets.UTF_8));
388	            StringBuilder sb = new StringBuilder(digest.length * 2);
389	            for (byte b : digest) {
390	                sb.append(String.format("%02x", b));
391	            }
392	            return sb.substring(0, 12).toUpperCase();
393	        }
394	        catch (NoSuchAlgorithmException e) {
395	            throw new IllegalStateException("SHA-256 not available", e);
396	        }
397	    }
398	
399	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
400	    @Override
401	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
402	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
403	        if (currentOwner == null) {
404	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
405	        }
406	        currentOwner.setAddress(ownerFieldsDto.getAddress());
407	        currentOwner.setCity(ownerFieldsDto.getCity());
408	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
409	        currentOwner.setLastName(ownerFieldsDto.getLastName());
410	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
411	        this.clinicService.saveOwner(currentOwner);
412	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
413	    }
414	
415	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
416	    @Transactional
417	    @Override
418	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
419	        Owner owner = this.clinicService.findOwnerById(ownerId);
420	        if (owner == null) {
421	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
422	        }
423	        this.clinicService.deleteOwner(owner);
424	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
425	    }
426	
427	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
428	    @Override
429	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
430	        Owner owner = this.clinicService.findOwnerById(ownerId);
431	        if (owner == null) {
432	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
433	        }
434	        HttpHeaders headers = new HttpHeaders();
435	        Pet pet = petMapper.toPet(petFieldsDto);
436	        owner.setId(ownerId);
437	        pet.setOwner(owner);
438	        pet.getType().setName(null);
439	        this.clinicService.savePet(pet);
440	        PetDto petDto = petMapper.toPetDto(pet);
441	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
442	            .buildAndExpand(pet.getId()).toUri());
443	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
444	    }
445	
446	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
447	    @Override
448	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
449	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
450	        if (currentOwner != null) {
451	            Pet currentPet = this.clinicService.findPetById(petId);
452	            if (currentPet != null) {
453	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
454	                currentPet.setName(petFieldsDto.getName());
455	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
456	                this.clinicService.savePet(currentPet);
457	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
458	            }
459	        }
460	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
461	    }
462	
463	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
464	    @Override
465	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
466	        HttpHeaders headers = new HttpHeaders();
467	        Visit visit = visitMapper.toVisit(visitFieldsDto);
468	        Pet pet = new Pet();
469	        pet.setId(petId);
470	        visit.setPet(pet);
471	        this.clinicService.saveVisit(visit);
472	        VisitDto visitDto = visitMapper.toVisitDto(visit);
473	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
474	            .buildAndExpand(visit.getId()).toUri());
475	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
476	    }
477	
478	
479	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
480	    @Override
481	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
482	        Owner owner = this.clinicService.findOwnerById(ownerId);
483	        if (owner != null) {
484	            Pet pet = owner.getPet(petId);
485	            if (pet != null) {
486	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
487	            }
488	        }
489	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
490	    }
491	}
