146	        this.bulkSignupWarning = bulkSignupWarning;
147	    }
148	
149	    public Integer getHouseholdSize() {
150	        return this.householdSize;
151	    }
152	
153	    public void setHouseholdSize(Integer householdSize) {
154	        this.householdSize = householdSize;
155	    }
156	
157	    /**
158	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
159	     */
160	    public String getDisplayName() {
161	        return this.getLastName() + ", " + this.getFirstName();
162	    }
163	
164	    /**
165	     * The owner's initials: the upper-cased first letters of firstName and lastName,
166	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
167	     */
168	    public String getInitials() {
169	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
170	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
171	    }
172	
173	    /**
174	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
175	     * last two digits of the registrationDate year, e.g. {@code 'LON-SMI-0007-M26'}.
176	     */
177	    public String getMembershipNumber() {
178	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
179	    }
180	
181	    /** Fixed city-to-region table used to derive an owner's locality. */
182	    private static final Map<String, String> CITY_REGION = Map.of(
183	        "Sydney", "NSW",
184	        "Melbourne", "VIC",
185	        "Brisbane", "QLD");
186	
187	    /**
188	     * The owner's locality: the canonical region derived from the city using the fixed
189	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
190	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the table.
191	     */
192	    public String getLocality() {
193	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
194	    }
195	
196	    /**
197	     * The owner's membership level, a number from 1 to 3 determined on creation: it starts at 1,
198	     * gains 1 when an email is present, gains 1 when namesakeCount is 0, and is capped at 3.
199	     * Level 4 is reserved for tenure.
200	     */
201	    public Integer getMembershipLevel() {
202	        int level = 1;
203	        if (this.email != null && !this.email.isEmpty()) {
204	            level++;
205	        }
206	        if (this.namesakeCount != null && this.namesakeCount == 0) {
207	            level++;
208	        }
209	        return Math.min(level, 3);
210	    }
211	
212	    /**
213	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
214	     * otherwise {@code 'PHONE'}.
215	     */
216	    public String getContactPreference() {
217	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
218	    }
219	
220	    protected Set<Pet> getPetsInternal() {
221	        if (this.pets == null) {
222	            this.pets = new HashSet<>();
223	        }
224	        return this.pets;
225	    }
226	
227	    protected void setPetsInternal(Set<Pet> pets) {
228	        this.pets = pets;
229	    }
230	
231	    public List<Pet> getPets() {
232	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
233	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
234	        return Collections.unmodifiableList(sortedPets);
235	    }
